   199	                    parent,
   200	                    ..Node::default()
   201	                };
   202	                if parent != no_slot() {
   203	                    let parent_index = parent as usize;
   204	                    let parent_node = nodes.get(parent_index).ok_or_else(|| parse_error(DocumentError::Parse))?;
   205	                    let previous_last = parent_node.last_child;
   206	                    if parent_node.first_child == no_slot() { nodes[parent_index].first_child = slot; }
   207	                    else {
   208	                        let previous = nodes.get_mut(previous_last as usize).ok_or_else(|| parse_error(DocumentError::Parse))?;
   209	                        previous.next_sibling = slot;
   210	                    }
   211	                    nodes[parent_index].last_child = slot;
   212	                } else if parent == no_slot() {
   213	                    if root.replace(slot).is_some() { return Err(parse_error(DocumentError::Parse)); }
   214	                } else {
   215	                    return Err(parse_error(DocumentError::Parse));
   216	                }
   217	
   218	                index += 1;
   219	                while let Some(attribute) = tokens.get(index).filter(|next| next.kind == TokenKind::Attribute) {
   220	                    if cancel() { return Err(TableFailure::Canceled { offset: attribute.source.offset }); }
   221	                    if attributes.len() >= attribute_count || attribute.name.slice(source).is_none()
   222	                        || attribute.value.slice(source).is_none() || checked_span(attribute.source, source).is_none()
   223	                    {
   224	                        return Err(parse_error(DocumentError::Parse));
   225	                    }
   226	                    attributes.push(Attribute { name: attribute.name, value: attribute.value });
   227	                    node.attribute_count += 1;
   228	                    index += 1;
   229	                }
   230	                nodes.push(node);
   231	                if token.kind == TokenKind::StartElement {
   232	                    if stack.len() >= MAX_DEPTH { return Err(parse_error(DocumentError::Limit)); }
   233	                    stack.push(slot);
   234	                }
   235	            }
   236	            TokenKind::EndElement => {
   237	                let Some(slot) = stack.pop() else { return Err(parse_error(DocumentError::Parse)); };
   238	                let node = nodes.get_mut(slot as usize).ok_or_else(|| parse_error(DocumentError::Parse))?;
   239	                let end = token.source.offset.checked_add(token.source.length).ok_or_else(|| parse_error(DocumentError::Parse))?;
   240	                let node_end = node.source.offset.checked_add(node.source.length).ok_or_else(|| parse_error(DocumentError::Parse))?;
   241	                if node.source.offset > token.source.offset || end < node_end || end > source.len()
   242	                    || token.name.slice(source).is_none()
   243	                {
   244	                    return Err(parse_error(DocumentError::Parse));
   245	                }
   246	                node.source.length = end.checked_sub(node.source.offset).ok_or(DocumentError::Parse)?;
   247	                index += 1;
   248	            }
   249	            _ => index += 1,
   250	        }
   251	    }
   252	    if !stack.is_empty() || nodes.len() != node_count || attributes.len() != attribute_count {
   253	        return Err(parse_error(DocumentError::Parse));
   254	    }
   255	    Ok((nodes, attributes, root.ok_or(DocumentError::Parse)?))
   256	}
