    57	impl DocumentCore {
    58	    pub(crate) fn from_parts(
    59	        id: u64,
    60	        nodes: Vec<Node>,
    61	        attributes: Vec<Attribute>,
    62	        root: Option<u32>,
    63	    ) -> Self {
    64	        let live_node_count = nodes.len();
    65	        Self { id, nodes, attributes, live_node_count, root }
    66	    }
    67	
    68	    pub fn document_id(&self) -> u64 { self.id }
    69	    pub fn node_count(&self) -> usize { self.nodes.len() }
    70	    pub fn live_node_count(&self) -> usize { self.live_node_count }
    71	
    72	    pub fn root(&self) -> Option<DocumentHandle> {
    73	        let slot = self.root?;
    74	        self.nodes.get(slot as usize).filter(|node| node.live)?;
    75	        Some(self.handle(slot))
    76	    }
    77	
    78	    pub fn first_child(&self, parent: DocumentHandle) -> Option<DocumentHandle> {
    79	        let node = self.resolve(parent)?;
    80	        let mut child = node.first_child;
    81	        while child != NO_SLOT {
    82	            let current = self.nodes.get(child as usize)?;
    83	            if current.live { return Some(self.handle(child)); }
    84	            child = current.next_sibling;
    85	        }
    86	        None
    87	    }
    88	
    89	    pub fn next_sibling(&self, handle: DocumentHandle) -> Option<DocumentHandle> {
    90	        let node = self.resolve(handle)?;
    91	        let mut sibling = node.next_sibling;
    92	        while sibling != NO_SLOT {
    93	            let current = self.nodes.get(sibling as usize)?;
    94	            if current.live { return Some(self.handle(sibling)); }
    95	            sibling = current.next_sibling;
    96	        }
    97	        None
    98	    }
    99	
   100	    pub fn parent(&self, handle: DocumentHandle) -> Option<DocumentHandle> {
   101	        let node = self.resolve(handle)?;
   102	        if node.parent == NO_SLOT { return None; }
   103	        self.nodes.get(node.parent as usize).filter(|parent| parent.live)?;
   104	        Some(self.handle(node.parent))
   105	    }
   106	
   107	    pub fn attribute_count(&self, handle: DocumentHandle) -> usize {
   108	        self.resolve(handle).map_or(0, |node| node.attribute_count)
   109	    }
   110	
   111	    fn attribute_spans(&self, handle: DocumentHandle, index: usize) -> Option<(vexel_xml::XmlSpan, vexel_xml::XmlSpan)> {
   112	        let node = self.resolve(handle)?;
   113	        if index >= node.attribute_count { return None; }
   114	        let attribute = self.attributes.get(node.first_attribute.checked_add(index)?)?;
   115	        Some((attribute.name, attribute.value))
   116	    }
   117	
   118	    pub fn depth(&self, handle: DocumentHandle) -> Option<usize> {
   119	        Some(self.resolve(handle)?.depth)
   120	    }
   121	
   122	    pub fn node_at(&self, slot: usize) -> Option<DocumentHandle> {
   123	        let index = u32::try_from(slot).ok()?;
   124	        self.nodes.get(slot).filter(|node| node.live)?;
   125	        Some(self.handle(index))
   126	    }
   127	
   128	    pub fn source_span(&self, handle: DocumentHandle) -> Option<DocumentSourceSpan> {
   129	        Some(self.resolve(handle)?.source)
   130	    }
   131	
   132	    /// Removes a node and all descendants. Slots remain stable; each live
   133	    /// generation advances so previously issued handles cannot resolve.
   134	    pub fn remove_subtree(&mut self, handle: DocumentHandle) -> bool {
   135	        if self.resolve(handle).is_none() { return false; }
   136	        for index in 0..self.nodes.len() {
   137	            if !self.is_descendant_or_self(index, handle.slot as usize) { continue; }
   138	            let node = &mut self.nodes[index];
   139	            if node.live {
   140	                node.live = false;
   141	                self.live_node_count -= 1;
   142	                if node.generation != u32::MAX { node.generation += 1; }
   143	            }
   144	        }
   145	        if self.root == Some(handle.slot) { self.root = None; }
   146	        true
   147	    }
   148	
   149	    fn is_descendant_or_self(&self, index: usize, ancestor: usize) -> bool {
   150	        let mut current = index;
   151	        loop {
   152	            if current == ancestor { return true; }
   153	            let Some(node) = self.nodes.get(current) else { return false; };
   154	            if node.parent == NO_SLOT { return false; }
   155	            current = node.parent as usize;
   156	        }
   157	    }
   158	
   159	    fn resolve(&self, handle: DocumentHandle) -> Option<&Node> {
   160	        if handle.document_id != self.id { return None; }
   161	        let node = self.nodes.get(handle.slot as usize)?;
   162	        (node.live && node.generation == handle.generation).then_some(node)
   163	    }
   164	
   165	    fn handle(&self, slot: u32) -> DocumentHandle {
   166	        DocumentHandle { document_id: self.id, slot, generation: self.nodes[slot as usize].generation }
   167	    }
   168	}
