   186	macro_rules! document_query_methods {
   187	    ($bytes:ty) => {
   188	            pub fn document_id(&self) -> u64 { self.core.document_id() }
   189	            pub fn source(&self) -> $bytes { &self.source }
   190	            pub fn node_count(&self) -> usize { self.core.node_count() }
   191	            pub fn live_node_count(&self) -> usize { self.core.live_node_count() }
   192	            pub fn root(&self) -> Option<DocumentHandle> { self.core.root() }
   193	            pub fn first_child(&self, parent: DocumentHandle) -> Option<DocumentHandle> { self.core.first_child(parent) }
   194	            pub fn next_sibling(&self, handle: DocumentHandle) -> Option<DocumentHandle> { self.core.next_sibling(handle) }
   195	            pub fn parent(&self, handle: DocumentHandle) -> Option<DocumentHandle> { self.core.parent(handle) }
   196	            pub fn tag_name(&self, handle: DocumentHandle) -> Option<$bytes> {
   197	                self.core.resolve(handle)?.name.slice(&self.source)
   198	            }
   199	            pub fn attribute_count(&self, handle: DocumentHandle) -> usize { self.core.attribute_count(handle) }
   200	            pub fn attribute_at(&self, handle: DocumentHandle, index: usize) -> Option<($bytes, $bytes)> {
   201	                let (name, value) = self.core.attribute_spans(handle, index)?;
   202	                Some((name.slice(&self.source)?, value.slice(&self.source)?))
   203	            }
   204	            pub fn depth(&self, handle: DocumentHandle) -> Option<usize> { self.core.depth(handle) }
   205	            pub fn node_at(&self, slot: usize) -> Option<DocumentHandle> { self.core.node_at(slot) }
   206	            pub fn source_span(&self, handle: DocumentHandle) -> Option<DocumentSourceSpan> { self.core.source_span(handle) }
   207	            pub fn remove_subtree(&mut self, handle: DocumentHandle) -> bool { self.core.remove_subtree(handle) }
   208	    };
   209	}
