 70	    fn fault<T>(&self, e: XmlError, at: usize) -> Result<T, Fault> { Err(Fault(e, at.min(self.src.len()))) }
 71	    fn emit(&mut self, token: XmlToken, at: usize) -> Result<(), Fault> {
 72	        if self.tokens.len() >= self.token_capacity { return self.fault(XmlError::OutputExhausted, at); }
 73	        if self.tokens.try_reserve(1).is_err() { return self.fault(XmlError::OutputExhausted, at); }
 74	        self.tokens.push(token); self.result.token_count += 1; Ok(())
 75	    }
 76	    fn node(&mut self, at: usize) -> Result<(), Fault> {
 77	        let n = self.result.node_count.checked_add(1).ok_or(Fault(XmlError::NodeLimit, at))?;
 78	        if n > self.limits.nodes { return self.fault(XmlError::NodeLimit, at); } self.result.node_count = n; Ok(())
 79	    }
 80	    fn starts(&self, b: usize, lit: &[u8]) -> bool { self.src.get(b..b.saturating_add(lit.len())) == Some(lit) }
 81	    fn ws(&self, p: &mut usize) { while self.src.get(*p).is_some_and(|b| is_xml_whitespace(*b)) { *p += 1; } }
 82	    fn name(&self, p: &mut usize, qname: bool) -> Result<(XmlSpan, XmlSpan, XmlSpan), Fault> {
 83	        let start = *p; let Some((cp, mut q)) = utf8_next(self.src, *p) else { return self.fault(XmlError::InvalidName, start) };
 84	        if !is_name_start(cp) { return self.fault(XmlError::InvalidName, start); }
 85	        let mut colon = None;
 86	        while q < self.src.len() {
 87	            let before = q; let Some((cp, next)) = utf8_next(self.src, q) else { return self.fault(XmlError::InvalidUtf8, q) };
 88	            if !is_name_char(cp) { break; }
 89	            if cp == 0x3a { if qname && colon.is_some() { return self.fault(XmlError::InvalidName, colon.unwrap_or(before)); } if colon.is_none() { colon = Some(before); } }
 90	            q = next;
 91	        }
 92	        if q - start > MAX_TOKEN_NAME_BYTES { return self.fault(XmlError::MalformedSyntax, start); }
 93	        if qname && (self.src.get(start) == Some(&b':') || self.src.get(q.saturating_sub(1)) == Some(&b':')) {
 94	            return self.fault(XmlError::InvalidName, start);
 95	        }
 96	        let name = XmlSpan { offset: start, length: q - start };
 97	        let (prefix, local) = match colon {
 98	            Some(c) => (XmlSpan { offset: start, length: c - start }, XmlSpan { offset: c + 1, length: q - c - 1 }),
 99	            None => (XmlSpan { offset: start, length: 0 }, name),
100	        };
